def order(a, n):
    """Finds the multiplicative order of a modulo n."""
    if a == 0:
        return None
    a = a % n
    for k in range(1, n + 1):
        if pow(a, k, n) == 1:
            return k
    return None

# We are looking for the order of 3 modulo 625
k2 = order(3, 625)
print(f"Order of 3 mod 625: {k2}")

